import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import { z } from 'zod';

const server = new McpServer({ name: 'weather-service', version: '1.0.0' });

// 注册工具：模型可通过 tools/call 调用
server.tool(
  'getWeather',
  { city: z.string().describe('城市名称') },
  async ({ city }) => {
    try {
      // 实际项目中这里调用天气 API 或数据库
      const data = await fetchWeather(city);
      return {
        content: [{ type: 'text', text: `${city}: ${data.condition} ${data.temp}°C` }]
      };
    } catch (err) {
      return {
        isError: true,
        content: [{ type: 'text', text: `查询失败: ${err.message}` }]
      };
    }
  }
);

// 注册资源：模型可通过 resources/read 读取
server.resource(
  'city-list',
  'weather://cities',
  async (uri) => ({
    contents: [{ uri: uri.href, text: '北京, 上海, 广州, 深圳' }]
  })
);

const transport = new StdioServerTransport();
await server.connect(transport);

async function fetchWeather(city: string) {
  // 模拟外部调用
  return { condition: '晴', temp: 25 };
}
